(()=>{
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');
const roster=[
 {name:'NARUTO',role:'HIDDEN LEAF · JINCHURIKI',desc:'Never back down. Never break your word.',coat:'#e77b32',glow:'#ed8e44',mark:'火',skin:'#e3ae83',hair:'#f1c74c',accent:'#3977bd'},
 {name:'SASUKE',role:'HIDDEN LEAF · AVENGER',desc:'The past is a shadow. The future is mine.',coat:'#454963',glow:'#797ba2',mark:'雷',skin:'#e5c4ad',hair:'#161921',accent:'#b54f66'},
 {name:'KAKASHI',role:'HIDDEN LEAF · COPY NINJA',desc:'Those who abandon their friends are worse than scum.',coat:'#526875',glow:'#708e99',mark:'写',skin:'#dcb69c',hair:'#c4c6cf',accent:'#3d6c9e'},
 {name:'ITACHI',role:'AKATSUKI · PRODIGY',desc:'People live their lives bound by what they accept as correct.',coat:'#8a303a',glow:'#aa4550',mark:'暁',skin:'#d8b7a4',hair:'#21191b',accent:'#1e1a20'},
 {name:'MADARA',role:'UCHIHA · GHOST OF THE UCHIHA',desc:'Wake up to reality. Nothing ever goes as planned.',coat:'#702d39',glow:'#a94148',mark:'斑',skin:'#d7aa96',hair:'#191a25',accent:'#a33845'},
 {name:'SAKURA',role:'HIDDEN LEAF · MEDICAL NIN',desc:'I will no longer be a burden to my friends.',coat:'#b75b68',glow:'#d77b89',mark:'桜',skin:'#efc7ae',hair:'#e891aa',accent:'#6c5891'}
];
const arenas=[{name:'HIDDEN LEAF · TRAINING GROUNDS',sky:['#8199a0','#d3c3a5'],ground:'#716d5f'},{name:'VALLEY OF THE END · RIVERBANK',sky:['#737d89','#d1a888'],ground:'#646c66'},{name:'THE HIDDEN SAND · DUNE SEA',sky:['#a5765d','#e3bc84'],ground:'#9b7955'}];
let W=0,H=0,dpr=1,state='intro',selected=0,mode='story',arena=0,player,enemy,keys={},last=0,elapsed=0,elapsedBattle=0,shake=0,fx=[],totalHits=0,jutsuUsed=0,combo=0,comboTimer=0,lockOn=true,paused=false,sound=true,round=1,raf;
const $=s=>document.querySelector(s),clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a);
function resize(){dpr=Math.min(devicePixelRatio||1,2);const r=canvas.getBoundingClientRect();W=r.width;H=r.height;canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}window.addEventListener('resize',resize);resize();
function buildRoster(){const root=$('#roster');root.innerHTML='';roster.forEach((f,i)=>{const b=document.createElement('button');b.className='fighter-card'+(i===selected?' active':'');b.innerHTML=`<span class="card-art" data-mark="${f.mark}" style="--glow:${f.glow};--coat:${f.coat}"></span><span class="card-num">0${i+1}</span><span class="card-name">${f.name}</span>`;b.onclick=()=>select(i);root.appendChild(b)});select(selected)}
function select(i){selected=i;document.querySelectorAll('.fighter-card').forEach((b,j)=>b.classList.toggle('active',i===j));$('#fighterName').textContent=roster[i].name;$('#fighterDesc').textContent=roster[i].desc;$('.role').textContent=roster[i].role;$('.select-count').innerHTML=`0${i+1} <span>/</span> 06`;$('.portrait.p1').textContent=roster[i].mark;$('.portrait.p1').style.background=`linear-gradient(135deg,${roster[i].glow},${roster[i].coat})`}
function show(id){['intro','selectScreen','modeScreen','battleUI','resultScreen'].forEach(x=>$('#'+x).classList.toggle('hidden',x!==id))}
$('#playBtn').onclick=()=>{state='select';show('selectScreen');buildRoster()};$('#fightBtn').onclick=()=>{state='mode';show('modeScreen')};$('#backSelect').onclick=()=>{state='select';show('selectScreen')};document.querySelectorAll('.mode-card').forEach(b=>b.onclick=()=>{document.querySelectorAll('.mode-card').forEach(c=>c.classList.remove('selected'));b.classList.add('selected');mode=b.dataset.mode});$('#startFight').onclick=startBattle;
$('#soundBtn').onclick=()=>{sound=!sound;$('#soundBtn b').textContent=sound?'SOUND ON':'SOUND OFF'};
$('#exitBattle').onclick=()=>{if(state!=='battle')return;paused=!paused;pauseOverlay()};
function pauseOverlay(){let el=$('#pauseModal');if(!el){el=document.createElement('div');el.id='pauseModal';el.className='pause-modal';el.innerHTML='<div class="pause-box"><h2>BATTLE PAUSED</h2><button class="primary-btn" id="resumeBtn">RESUME <span>→</span></button><br><button class="text-btn" id="quitBtn">RETURN TO MENU</button></div>';$('.game-wrap').appendChild(el);$('#resumeBtn').onclick=()=>{paused=false;el.remove()};$('#quitBtn').onclick=()=>{paused=false;el.remove();state='select';show('selectScreen')}}else el.remove()}
$('#rematchBtn').onclick=startBattle;$('#menuBtn').onclick=()=>{state='select';show('selectScreen');buildRoster()};
function fighter(id,index,x,z){return{id,index,data:roster[index],x,z,hp:100,chakra:0,face:1,attackCd:0,stun:0,dodge:0,anim:0,transform:0,flash:0}}
function startBattle(){state='battle';paused=false;elapsedBattle=0;totalHits=0;jutsuUsed=0;combo=0;comboTimer=0;round=1;arena=mode==='story'?0:Math.floor(Math.random()*arenas.length);player=fighter('p',selected,-2,-1);const foeIdx=mode==='story'?(selected+1+(round-1))%roster.length:Math.floor(Math.random()*roster.length);enemy=fighter('e',foeIdx,2,1);if(enemy.index===selected)enemy=fighter('e',(foeIdx+1)%roster.length,2,1);$('#pName').textContent=player.data.name;$('#eName').textContent=enemy.data.name;$('.portrait.p2').textContent=enemy.data.mark;$('.portrait.p2').style.background=`linear-gradient(135deg,${enemy.data.glow},${enemy.data.coat})`;$('#arenaName').textContent=arenas[arena].name;$('#roundLabel').textContent=`ROUND 0${round}`;$('#battleMessage').innerHTML='ROUND 01 <strong>FIGHT!</strong>';$('#battleMessage').style.opacity=1;show('battleUI');setTimeout(()=>{if(state==='battle')$('#battleMessage').style.opacity=0},1300);fx=[]}
function project(x,z){const scale=.72+(z+7)*.038;return{x:W*.5+(x-(lockOn&&state==='battle'?(player.x+enemy.x)*.5:0))*W*.067*scale,y:H*.53+(z*.045*H),s:scale}}
function drawBackground(){const sky=ctx.createLinearGradient(0,0,0,H*.68);sky.addColorStop(0,arenas[arena].sky[0]);sky.addColorStop(1,arenas[arena].sky[1]);ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);const sun=ctx.createRadialGradient(W*.76,H*.22,4,W*.76,H*.22,H*.28);sun.addColorStop(0,'#ffe9c482');sun.addColorStop(1,'#ffe9c400');ctx.fillStyle=sun;ctx.fillRect(0,0,W,H*.65);
// distant mountain silhouettes
for(let layer=0;layer<3;layer++){ctx.beginPath();const base=H*(.49+layer*.045);ctx.moveTo(0,base);for(let x=0;x<=W+40;x+=Math.max(28,W/16)){const y=base-rand(7,28)*(layer===0?.8:1);ctx.lineTo(x,y)}ctx.lineTo(W,H*.66);ctx.lineTo(0,H*.66);ctx.closePath();ctx.fillStyle=['#687376','#73766f','#77776c'][layer];ctx.globalAlpha=.54+layer*.12;ctx.fill();ctx.globalAlpha=1}
if(arena===0){drawGate(W*.18,H*.43,.7);drawGate(W*.83,H*.42,.57);for(let i=0;i<6;i++)drawTree(W*(.02+i*.19),H*(.47+Math.sin(i*9)*.012),.55+(i%3)*.1)}else if(arena===1){drawStatue(W*.15,H*.36,.8);drawStatue(W*.85,H*.38,.7);for(let i=0;i<5;i++)drawTree(W*(.05+i*.22),H*.49,.48)}else{for(let i=0;i<7;i++){const x=i*W/5-W*.1;ctx.beginPath();ctx.moveTo(x,H*.53);ctx.lineTo(x+W*.15,H*(.35+(i%2)*.08));ctx.lineTo(x+W*.3,H*.53);ctx.fillStyle='#9f795d';ctx.fill()}for(let i=0;i<5;i++)drawTree(W*(.08+i*.23),H*.5,.43)}
// ground perspective
ctx.beginPath();ctx.moveTo(0,H*.52);ctx.lineTo(W,H*.52);ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.closePath();ctx.fillStyle=arenas[arena].ground;ctx.fill();const grad=ctx.createLinearGradient(0,H*.51,0,H);grad.addColorStop(0,'#ffffff0d');grad.addColorStop(1,'#171b2299');ctx.fillStyle=grad;ctx.fillRect(0,H*.51,W,H*.49);
// arena edge markings and perspective lines
ctx.strokeStyle='#e7d8be19';ctx.lineWidth=1;for(let i=-8;i<=8;i++){ctx.beginPath();ctx.moveTo(W/2+i*W*.022,H*.52);ctx.lineTo(W/2+i*W*.13,H);ctx.stroke()}for(let i=0;i<6;i++){let t=i/6,y=H*(.54+t*t*.45);ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}
if(arena===0){for(let i=0;i<16;i++){const x=(i*173+elapsed*5)%W,y=H*(.51+(i%6)*.08);ctx.fillStyle=`#d49c6a${i%2?'20':'36'}`;ctx.beginPath();ctx.ellipse(x,y,2+(i%3),1.5,0,0,Math.PI*2);ctx.fill()}}
}
function drawGate(x,y,s){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#554a42';ctx.fillRect(-62,4,13,91);ctx.fillRect(49,4,13,91);ctx.fillStyle='#9e4739';ctx.fillRect(-72,0,144,14);ctx.fillRect(-52,21,104,10);ctx.fillStyle='#343638';ctx.fillRect(-23,9,46,16);ctx.fillStyle='#bba078';ctx.fillRect(-3,4,6,16);ctx.restore()}
function drawTree(x,y,s){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#55463c';ctx.fillRect(-3,0,6,37);for(let i=0;i<3;i++){ctx.beginPath();ctx.arc((i-1)*15,-4-i*11,18,0,Math.PI*2);ctx.fillStyle=['#536556','#4c6355','#5f6b58'][i];ctx.fill()}ctx.restore()}
function drawStatue(x,y,s){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#6b6660';ctx.beginPath();ctx.moveTo(-26,65);ctx.lineTo(-24,4);ctx.lineTo(-13,-12);ctx.lineTo(0,-32);ctx.lineTo(13,-11);ctx.lineTo(25,4);ctx.lineTo(27,65);ctx.fill();ctx.fillStyle='#8c8175';ctx.fillRect(-29,60,58,8);ctx.restore()}

input.newString:
function drawStatue(x,y,s){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#6b6660';ctx.beginPath();ctx.moveTo(-26,65);ctx.lineTo(-24,4);ctx.lineTo(-13,-12);ctx.lineTo(0,-32);ctx.lineTo(13,-11);ctx.lineTo(25,4);ctx.lineTo(27,65);ctx.fill();ctx.fillStyle='#8c8175';ctx.fillRect(-29,60,58,8);ctx.restore()}
function polygon(points,color){ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fill()}
function drawFighter(f){const p=project(f.x,f.z),scale=p.s*(H/650);const facing=(f.id==='p'?(enemy?Math.sign(enemy.x-f.x):1):Math.sign(player.x-f.x))||1;f.face=facing;ctx.save();ctx.translate(p.x,p.y);ctx.scale(scale*facing,scale);const bob=Math.sin(f.anim*9)*1.5,stagger=f.stun>0?Math.sin(elapsed*55)*3:0;ctx.translate(stagger,bob);
// grounding shadow and lock-on sigil
ctx.fillStyle='#17171966';ctx.beginPath();ctx.ellipse(0,0,27,8,0,0,Math.PI*2);ctx.fill();if(f.id==='e'&&lockOn){ctx.strokeStyle='#ff805caa';ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(0,2,31,9,0,Math.PI,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.moveTo(-31,0);ctx.lineTo(-31,-7);ctx.lineTo(-24,-7);ctx.moveTo(31,0);ctx.lineTo(31,-7);ctx.lineTo(24,-7);ctx.stroke()}
ctx.translate(0,-41);if(f.dodge>0){ctx.globalAlpha=.55}if(f.flash>0&&Math.floor(flashTime(f))%2===0)ctx.globalAlpha=.45;
// legs and sandals
const stride=Math.sin(f.anim*10)*(f.moving?5:1);polygon([[-12,14],[-3,14],[-5,32+stride],[-13,32+stride]],'#25272d');polygon([[3,14],[12,14],[14,32-stride],[6,32-stride]],'#25272d');ctx.fillStyle='#302c2a';ctx.fillRect(-15,30+stride,11,4);ctx.fillRect(6,30-stride,11,4);
// tunic silhouette
polygon([[-12,-5],[-8,-12],[9,-12],[14,-4],[20,20],[12,24],[-14,24],[-20,18]],f.data.coat);polygon([[-8,-10],[0,-4],[8,-10],[12,17],[-12,17]],f.data.accent);ctx.fillStyle='#20242c';ctx.fillRect(-13,15,27,4);ctx.fillStyle='#d5ba9a';ctx.fillRect(-12,19,24,2);
// arms
const swing=f.attackCd>0?Math.sin(f.attackCd*30)*10:stride*.5;ctx.lineCap='round';ctx.lineWidth=7;ctx.strokeStyle=f.data.coat;ctx.beginPath();ctx.moveTo(-12,-4);ctx.lineTo(-18+swing,-1);ctx.lineTo(-19+swing,9);ctx.stroke();ctx.beginPath();ctx.moveTo(12,-5);ctx.lineTo(18-swing,0);ctx.lineTo(18-swing,9);ctx.stroke();ctx.fillStyle=f.data.skin;ctx.beginPath();ctx.arc(-19+swing,10,3.8,0,Math.PI*2);ctx.arc(18-swing,10,3.8,0,Math.PI*2);ctx.fill();
// face, hair, headband
ctx.fillStyle=f.data.skin;ctx.beginPath();ctx.ellipse(0,-19,10.5,12,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=f.data.hair;ctx.beginPath();ctx.moveTo(-10,-19);ctx.lineTo(-13,-30);ctx.lineTo(-6,-27);ctx.lineTo(-3,-34);ctx.lineTo(1,-28);ctx.lineTo(8,-33);ctx.lineTo(10,-22);ctx.lineTo(6,-25);ctx.lineTo(1,-21);ctx.lineTo(-4,-25);ctx.lineTo(-8,-20);ctx.closePath();ctx.fill();ctx.fillStyle='#292b31';ctx.fillRect(-10,-24,20,4);ctx.fillStyle='#b8b2a1';ctx.fillRect(-4,-24,8,3);ctx.fillStyle='#26252a';ctx.fillRect(3,-18,2,1.3);ctx.fillRect(-5,-18,2,1.3);
// headband tails
polygon([[-9,-23],[-13,-22],[-19,-18],[-13,-19]],'#313943');polygon([[9,-23],[13,-22],[20,-17],[13,-19]],'#313943');
// chakra aura
if(f.transform>0){ctx.globalAlpha=.24+Math.sin(elapsed*15)*.08;ctx.strokeStyle=f.id==='p'?'#ff9b48':'#8c81ff';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(0,-10,23+Math.sin(elapsed*12)*3,42,0,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1}
if(f.flash>0){ctx.globalAlpha=.17;ctx.fillStyle='#fff';ctx.beginPath();ctx.ellipse(0,-20,11,12,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}ctx.restore();
// health label only during low hp
if(f.hp<28){ctx.font='700 8px DM Sans';ctx.textAlign='center';ctx.fillStyle='#fff';ctx.fillText('!',p.x,p.y-55*scale)} }
function flashTime(f){return f.flash*20}
function drawEffects(dt){for(let i=fx.length-1;i>=0;i--){const a=fx[i];a.life-=dt;if(a.life<=0){fx.splice(i,1);continue}if(a.type==='bolt'){const t=1-a.life/a.max,x=a.x+(a.tx-a.x)*t,y=a.y+(a.ty-a.y)*t;ctx.save();ctx.globalAlpha=Math.min(1,a.life*2);ctx.shadowBlur=22;ctx.shadowColor=a.color;ctx.strokeStyle=a.color;ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(x-25,y+9);ctx.lineTo(x,y);ctx.lineTo(x+19,y-6);ctx.stroke();ctx.strokeStyle='#fff6d8';ctx.lineWidth=2;ctx.stroke();ctx.restore()}else{const p=project(a.x,a.z),r=(1-a.life/a.max)*a.size;ctx.globalAlpha=Math.max(0,a.life/a.max);ctx.strokeStyle=a.color;ctx.lineWidth=2;ctx.beginPath();ctx.arc(p.x,p.y-35*p.s,r,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1}}}
function addImpact(f,color='#ffc47d'){fx.push({type:'ring',x:f.x,z:f.z,life:.35,max:.35,size:9,color});for(let i=0;i<8;i++){const p=project(f.x,f.z);fx.push({type:'spark',x:f.x+rand(-.4,.4),z:f.z+rand(-.2,.2),life:.28,max:.28,size:rand(3,10),color})}}
function drawScene(dt){drawBackground();if(state==='battle'&&player&&enemy){const arr=[player,enemy].sort((a,b)=>a.z-b.z);arr.forEach(drawFighter);drawEffects(dt)}else{const demo1={...fighter('p',0,-2,-1),anim:elapsed, moving:false},demo2={...fighter('e',1,2,.8),anim:elapsed+.8,moving:false};drawFighter(demo1);drawFighter(demo2);drawEffects(dt)}
// cinematic light flecks
for(let i=0;i<18;i++){let x=(i*127+elapsed*(i%2?7:-4))%W,y=(i*47+elapsed*3)%H;if(y>H*.5){ctx.fillStyle='#fff6d033';ctx.fillRect(x,y,1,1)}}}

